(()=>{const e=new class{constructor(){this.loaderDoneListener=null}init(){console.log("About")}destroy(){this.loaderDoneListener&&(document.removeEventListener("loaderDone",this.loaderDoneListener),this.loaderDoneListener=null)}};e.loaderDoneListener=()=>e.init(),document.addEventListener("loaderDone",e.loaderDoneListener),window.aboutCleanup=()=>e.destroy()})();